rules:
@media (max-width: 1080px) {
  .main { padding: 36px 26px 58px; }
  .grid { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
  .card { min-height: 210px; padding: 18px; }
}

@media (max-width: 760px) {
  .topbar { gap: 9px; padding-inline: 14px; }
  .brand span:last-child { display: none; }
  .tabs { overflow: hidden; }
  .tab { min-width: 76px; }
  .space { max-width: 116px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .main { padding: 30px 18px 50px; }
  .hero, .subhead, .search { align-items: flex-start; flex-direction: column; }
  .grid { grid-template-columns: 1fr; }
  .assistant-boundary { grid-template-columns: 1fr; }
  .assistant-sidebar { display: none; }
}

@media (max-width: 640px) {
  .guard { display: grid; }
  .shell { visibility: hidden; }
}

